    expect(events).toEqual(['message_start', 'content_block_start', 'content_block_delta', 'content_block_stop', 'message_delta', 'message_stop'])
    expect(text).toContain('"text":"eco: hola"')
    expect(text).toContain('"stop_reason":"end_turn"')
  })
})

