    '--output-format', OUTPUT_FORMAT,
    '--input-format', INPUT_FORMAT,
    '--model', options.model,
    '--tools', '',
    ...(options.systemPrompt !== undefined ? ['--system-prompt', options.systemPrompt] : []),
    ...bridgeArgs(options.toolNames, options.bridgeUrl),
  ]
}

